const crypto = require('crypto');
const secret = $env.TGWITNESS_WEBHOOK_SECRET;
if (!secret) throw new Error('Receiver signing secret is not configured');
const item = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const header = item.json.headers['x-tgwitness-signature'] || '';
const match = /^t=(\d+),v1=([a-f0-9]{64})$/.exec(header);
if (!match || Math.abs(Date.now()/1000 - Number(match[1])) > 300) throw new Error('Expired or invalid signature');
const expected = crypto.createHmac('sha256', secret).update(match[1] + '.').update(raw).digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(match[2], 'hex'))) throw new Error('Signature mismatch');
const event = JSON.parse(raw.toString('utf8'));
if (event.schema !== 'tgwitness.webhook/1' || !/^[a-f0-9]{64}$/.test(event.event_id)) throw new Error('Unsupported event');
return [{json: {accepted: true, event_id: event.event_id, event}}];
